import{e as t,ab as a,a1 as i,m as o,r as n,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [April]","description":"April 2026 updates","frontmatter":{"title":"Monthly Updates [April]","description":"April 2026 updates","date":"2026-04-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/april-2026.md","filePath":"posts/april-2026.md"}'),l={name:"posts/april-2026.md"};function p(d,e,h,f,c,g){const r=a("Post");return i(),o("div",null,[n(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added a new <strong><a href="https://fmhy.net/other/backups" target="_blank" rel="noreferrer">Retro Style</a></strong> instance to our backups page. Thank you to ROI for making this. <a href="https://i.ibb.co/7JH9tB1B/image.png" target="_blank" rel="noreferrer">Screenshot</a> / <a href="https://i.imgur.com/fpPxo3y.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Added <a href="https://fmhy.net/audio#youtube-music-tools" target="_blank" rel="noreferrer">YouTube Music Tools</a> section to Audio. Thank you to Samidy for the idea.</p></li><li><p>Added <a href="https://fmhy.net/social-media-tools#bilibili-tools" target="_blank" rel="noreferrer">Bilibili Tools</a> section to Social Media. Thank you to Waflenoob for the idea.</p></li><li><p>Added <a href="https://fmhy.net/mobile#root-managers" target="_blank" rel="noreferrer">Root Managers</a> section to Android. Thank you to SyntaX for the idea.</p></li><li><p>Added <a href="https://fmhy.net/gaming-tools#fighting-tools" target="_blank" rel="noreferrer">Fighting Game</a> section to Gaming Tools.</p></li><li><p>Added <a href="https://fmhy.net/gaming-tools#visual-novel-tools" target="_blank" rel="noreferrer">Visual Novel</a> section to Gaming Tools.</p></li><li><p>Added <a href="https://fmhy.net/educational#lego" target="_blank" rel="noreferrer">LEGO</a> section to Hobbies.</p></li><li><p>Added <a href="https://fmhy.net/audio#karaoke-synced-lyrics" target="_blank" rel="noreferrer">Karaoke / Synced Lyrics</a> section to Audio.</p></li><li><p>Added <a href="https://fmhy.net/audio#genre-specific-radio" target="_blank" rel="noreferrer">Genre Specific Radio</a> section to Audio.</p></li><li><p>Added <a href="https://fmhy.net/educational#flashcards" target="_blank" rel="noreferrer">Flashcard Tools</a> section to Educational.</p></li><li><p>Added <a href="https://fmhy.net/educational#tech-history" target="_blank" rel="noreferrer">History of Technology</a> section to History.</p></li><li><p>Added <a href="https://fmhy.net/reading#declassified-leaked-documents" target="_blank" rel="noreferrer">Declassified / Leaked Documents</a> section to Reading.</p></li><li><p>Updated descriptions + added platform icons to <a href="https://fmhy.net/file-tools#file-converters" target="_blank" rel="noreferrer">File Converters</a>. Thank you to znarfm for doing this. <a href="https://i.ibb.co/23krrCSr/Untitled.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/veXdknP.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Added platform icons to <a href="https://fmhy.net/text-tools#note-taking" target="_blank" rel="noreferrer">Note-Taking</a> section. Thank you to RansomQ for doing this. <a href="https://i.ibb.co/LD08HynF/Untitled.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/wL927Bc.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Cleaned up <a href="https://fmhy.net/internet-tools#email-aliasing" target="_blank" rel="noreferrer">Email Aliasing</a>, updated descriptions, and added platform icons. Thank you to goose126 for doing this. <a href="https://i.ibb.co/3y9Gr4vZ/image.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/YTLBacb.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Cleaned up <a href="https://fmhy.net/privacy#dns-filters" target="_blank" rel="noreferrer">DNS Filters</a> + moved it out of storage into its own section. Thank you to Waflenoob for doing this. <a href="https://i.ibb.co/1JTF8Ym4/image.png" target="_blank" rel="noreferrer">Change List</a> / <a href="https://i.imgur.com/4xRj7qZ.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Cleaned up formatting in <a href="https://fmhy.net/audio#audio-ripping" target="_blank" rel="noreferrer">Audio Ripping Sites</a>. <a href="https://i.ibb.co/SXMvPMKq/24234.jpg" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/Npxu0MJ.jpeg" target="_blank" rel="noreferrer">2</a></p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/privacy#browser-privacy" target="_blank" rel="noreferrer">LibreWolf</a> in Browser Privacy. Custom privacy-focused version of Firefox, easily accessible, has good configs, and is well liked.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#email-privacy" target="_blank" rel="noreferrer">Tuta</a> in Email Privacy. Encrypted email, gives 1GB free, preferred over things like Proton Mail by some.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#social-media-apps" target="_blank" rel="noreferrer">Kettu</a> in Mobile Discord Clients. Modded client for both Android + iOS with plugin support, has been working well for those who have been testing it.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-streaming" target="_blank" rel="noreferrer">Nuvio</a> in Android Streaming. Was already starred in iOS, but Android users seem to be finding it useful. Has plugin support (including stremio), a nice UI, and weekly updates.</p></li><li><p>Starred <a href="https://fmhy.net/ai#official-model-sites" target="_blank" rel="noreferrer">Qwen</a> + <a href="https://fmhy.net/ai#specialized-chatbots" target="_blank" rel="noreferrer">Ask Brave</a> in AI section. Both are unlimited, and their models seem to be working well for people.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#privacy-indexes" target="_blank" rel="noreferrer">The OPSEC Bible</a> in Privacy Indexes. In-depth and well respected online anonymity guide.</p></li><li><p>Starred <a href="https://fmhy.net/downloading#foss-sites" target="_blank" rel="noreferrer">Is it really FOSS</a> in FOSS section. Database that helps determine if something is truly FOSS or not.</p></li><li><p>Starred <a href="https://fmhy.net/internet-tools#userscripts" target="_blank" rel="noreferrer">ScriptCat</a> in Userscript Managers. Open-source, MV3 compatible, allows background + scheduled scripts, considered by some to be the best current script manager.</p></li><li><p>Starred <a href="https://fmhy.net/reading#ebook-readers" target="_blank" rel="noreferrer">Readest</a> in Ebook Readers. Customizable, supports many formats and platforms, gives free cloud storage w/ progress sync.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#multi-game-sites" target="_blank" rel="noreferrer">Flash Museum</a> in Browser Game Sites. Has a clean UI + one of the bigger libraries of oldschool flash games.</p></li><li><p>Starred <a href="https://fmhy.net/internet-tools#paywall-bypass" target="_blank" rel="noreferrer">PressReleased</a> in Paywall Bypass. Based on Bypass Paywalls Clean, requires no extension.</p></li><li><p>Starred <a href="https://fmhy.net/internet-tools#redirect-bypass" target="_blank" rel="noreferrer">Evade</a> in Redirect Bypass. Fast, well maintained, and works on lots of sites.</p></li><li><p>Starred <a href="https://fmhy.net/educational#dictionaries-thesaurus" target="_blank" rel="noreferrer">Wiktionary</a> in Dictionary section. Well respected dictionary with lots of active contributors.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#vpn" target="_blank" rel="noreferrer">Mullvad + IVPN</a> in VPN section. Both are confirmed <a href="https://mullvad.net/en/blog/2023/4/20/mullvad-vpn-was-subject-to-a-search-warrant-customer-data-not-compromised/" target="_blank" rel="noreferrer">No-Logging</a> / <a href="https://www.ivpn.net/knowledgebase/privacy/how-do-we-react-when-requested-by-an-authority-for-information-relating-to-a-customer/" target="_blank" rel="noreferrer">2</a>, accept multiple payment types, and require no email.</p></li><li><p>Re-starred <a href="https://fmhy.net/privacy#proxy-sites" target="_blank" rel="noreferrer">HolyUnblocker</a> in Proxy Sites. Working well again, has built-in adblock + Tor support.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed P-Stream as their owners have decided to <a href="https://i.ibb.co/6RRB4YBj/image.png" target="_blank" rel="noreferrer">step back from the project</a> / <a href="https://i.imgur.com/xYIO9aK.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Removed Tampermonkey as it&#39;s had various issues over the years with things like their privacy policy, going closed-source, updates causing data loss, etc. and there&#39;s better options anyways (ScriptCat, Violentmonkey, Firemonkey).</p></li><li><p>Removed RTINGS as they&#39;ve gone <a href="https://www.rtings.com/company/revamping-our-membership-program" target="_blank" rel="noreferrer">fully paid</a>.</p></li><li><p>Unstarred ReVanced as Morphe is now stable enough to replace it + has more active development.</p></li><li><p>Unstarred Trakt as they&#39;re now <a href="https://redd.it/1rwgf8y" target="_blank" rel="noreferrer">forcing users onto v3 design</a> which is missing many features compared to previous version.</p></li></ul>',9))])}const b=t(l,[["render",p]]);export{u as __pageData,b as default};
